mapper.select:
 select
    0 as basBillNotAcc,
    (select ifnull(sum(i.billing_money),0) from billing_apply a
     left join billing_apply_imgs i on a.id = i.bill_id
     where a.billing_source = 3 and a.billing_state = 3 and i.state = 1 and i.id is not null

         and a.survey_consignor_id = #{entrustOrgId,jdbcType=BIGINT}

     ) as basTotalBillMoney,
    (select ifnull(sum(b.money),0) from billing_apply a
     left join billing_apply_accounts b on a.id = b.bill_id
     where a.billing_source = 3 and a.billing_state = 3 and b.state = 1 and b.id is not null

         and a.survey_consignor_id = #{entrustOrgId,jdbcType=BIGINT}

     ) as basTotalAccMoney,
   (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state = 2

       and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

   ) as basEntrustNotApv,
   (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (4,8,10,12,14,16) and s.org_assign = 0

         and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

   ) as basLefanNotAss,
   (
       select count(1) from (
           select r.id from survey_risk_case_info r
           left join survey_assign_org o on r.id = o.survey_info_id and o.org_survey_state in (1,2,5) and o.delete_flag = 0
           where r.delete_flag = 0 and o.id is not null

             and r.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

           group by r.id
       ) t
   ) as basOrgSurveying,
   (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (22,30)

       and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

   ) as basLefanApv,
   (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (24)

       and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

   ) as basEntrustApv,
   (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.entrust_report_end_date is not null and s.survey_phase != 3

       and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

   ) as basNotClose
from dual

select DATE_FORMAT(c.entrust_time,'%Y-%m-%d') reportDateStr,ifnull(count(1),0) newSurveyCaseNum from survey_risk_case_info r left join survey_risk_case c on r.survey_id = c.id left join survey_consignor n on r.entrust_org_id = n.id where r.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
and r.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
AND date_format(c.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(c.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
group by DATE_FORMAT(c.entrust_time,'%Y-%m-%d')

select DATE_FORMAT(c.entrust_time,'%Y-%m') reportDateStr,ifnull(count(1),0) newSurveyCaseNum from survey_risk_case_info r left join survey_risk_case c on r.survey_id = c.id left join survey_consignor n on r.entrust_org_id = n.id where r.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
and r.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
AND date_format(c.entrust_time,'%Y-%m') >= date_format(#{momTime,jdbcType=DATE},'%Y-%m')
AND date_format(c.entrust_time,'%Y-%m') < date_format(#{startTime,jdbcType=DATE},'%Y-%m')
group by DATE_FORMAT(c.entrust_time,'%Y-%m')

select DATE_FORMAT(r.entrust_report_end_date,'%Y-%m') reportDateStr,ifnull(count(1),0) newCheckNum from survey_risk_case_info r left join survey_risk_case c on r.survey_id = c.id left join survey_consignor n on r.entrust_org_id = n.id where r.delete_flag = 0 and r.entrust_report_end_date is not null
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
and r.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
AND date_format(r.entrust_report_end_date,'%Y-%m') >= date_format(#{momTime,jdbcType=DATE},'%Y-%m')
AND date_format(r.entrust_report_end_date,'%Y-%m') < date_format(#{endTime,jdbcType=DATE},'%Y-%m')
group by DATE_FORMAT(r.entrust_report_end_date,'%Y-%m')
